use rattler_conda_types::{
    conda_lock::CondaLock, version_spec::VersionOperator, MatchSpec, NamelessMatchSpec, Platform,
    Version, VersionSpec,
};

async fn update_environment(
    project: &Project,
    lock_file: &CondaLock,
    platform: Platform,
) -> miette::Result<()> {
    // Get the currently installed packages
    let prefix = Prefix::new(project.root().join(".pixi/env"))?;
    let installed_packages = prefix.find_installed_packages(None).await?;

    // Construct a transaction to bring the environment up to date with the lock-file content
    let transaction = Transaction::from_current_and_desired(
        installed_packages,
        get_required_packages(lock_file, platform)?,
        platform,
    )?;

    // Execute the transaction if there is work to do
    if !transaction.operations.is_empty() {
        // Execute the operations that are returned by the solver.
        await_in_progress(
            "updating environment",
            execute_transaction(
                transaction,
                prefix.root().to_path_buf(),
                rattler::default_cache_dir()?,
                AuthenticatedClient::default(),
            ),
        )
        .await?;
    }

    Ok(())
}

