25: /// Adds a dependency to the project
26: #[derive(Parser, Debug, Default)]
27: #[clap(arg_required_else_help = true)]
28: pub struct Args {
29:     /// Specify the dependencies you wish to add to the project.
30:     ///
31:     /// All dependencies should be defined as MatchSpec. If no specific version is
32:     /// provided, the latest version compatible with your project will be chosen automatically.
33:     ///
34:     /// Example usage:
35:     ///
36:     /// - `pixi add python=3.9`: This will select the latest minor version that complies with 3.9.*, i.e.,
37:     ///   python version 3.9.0, 3.9.1, 3.9.2, etc.
38:     ///
39:     /// - `pixi add python`: In absence of a specified version, the latest version will be chosen.
40:     ///   For instance, this could resolve to python version 3.11.3.* at the time of writing.
41:     ///
42:     /// Adding multiple dependencies at once is also supported:
43:     ///
44:     /// - `pixi add python pytest`: This will add both `python` and `pytest` to the project's dependencies.
45:     pub specs: Vec<MatchSpec>,
46: 
47:     /// The path to 'pixi.toml'
48:     #[arg(long)]
49:     pub manifest_path: Option<PathBuf>,
50: 
51:     /// This is a host dependency
52:     #[arg(long, conflicts_with = "build")]
53:     pub host: bool,
54: 
55:     /// This is a build dependency
56:     #[arg(long, conflicts_with = "host")]
57:     pub build: bool,
58: 
59:     /// Don't install the package to the environment, only add the package to the lock-file.
60:     #[arg(long)]
61:     pub no_install: bool,
62: }
63: 
64: #[derive(Debug, Copy, Clone)]
65: pub enum SpecType {
66:     Host,
67:     Build,
68:     Run,
69: }
70: 
71: impl SpecType {
72:     pub fn from_args(args: &Args) -> Self {
73:         if args.host {
74:             Self::Host
75:         } else if args.build {
76:             Self::Build
77:         } else {
78:             Self::Run
79:         }
80:     }
81: }
82: 
83: pub async fn execute(args: Args) -> miette::Result<()> {
84:     let mut project = Project::load_or_else_discover(args.manifest_path.as_deref())?;
85:     let spec_type = SpecType::from_args(&args);
86:     add_specs_to_project(&mut project, args.specs, spec_type, args.no_install).await
87: }
88: 
89: pub async fn add_specs_to_project(
90:     project: &mut Project,
91:     specs: Vec<MatchSpec>,
92:     spec_type: SpecType,
93:     no_install: bool,
94: ) -> miette::Result<()> {
95:     // Split the specs into package name and version specifier
96:     let new_specs = specs
97:         .into_iter()
98:         .map(|spec| match &spec.name {
99:             Some(name) => Ok((name.clone(), spec.into())),
100:             None => Err(miette::miette!("missing package name for spec '{spec}'")),
101:         })
102:         .collect::<miette::Result<HashMap<String, NamelessMatchSpec>>>()?;
103: 
104:     // Get the current specs
105: 
106:     // Fetch the repodata for the project
107:     let sparse_repo_data = project.fetch_sparse_repodata().await?;
108: 
109:     // Determine the best version per platform
110:     let mut best_versions = HashMap::new();
111:     for platform in project.platforms() {
112:         let current_specs = match spec_type {
113:             SpecType::Host => project.host_dependencies(*platform)?,
114:             SpecType::Build => project.build_dependencies(*platform)?,
115:             SpecType::Run => project.dependencies(*platform)?,
116:         };
117:         // Solve the environment with the new specs added
118:         let solved_versions = match determine_best_version(
119:             &new_specs,
120:             &current_specs,
121:             &sparse_repo_data,
122:             *platform,
123:         ) {
124:             Ok(versions) => versions,
125:             Err(err) => {
126:                 return Err(err).wrap_err_with(||miette::miette!(
127:                         "could not determine any available versions for {} on {platform}. Either the package could not be found or version constraints on other dependencies result in a conflict.",
128:                         new_specs.keys().join(", ")
129:                     ));
130:             }
131:         };
132: 
133:         // Determine the minimum compatible constraining version.
134:         for (name, version) in solved_versions {
135:             match best_versions.get_mut(&name) {
136:                 Some(prev) => {
137:                     if *prev > version {
138:                         *prev = version
139:                     }
140:                 }
141:                 None => {
142:                     best_versions.insert(name, version);
143:                 }
144:             }
145:         }
146:     }
147: 
148:     // Update the specs passed on the command line with the best available versions.
149:     let mut added_specs = Vec::new();
150:     for (name, spec) in new_specs {
151:         let best_version = best_versions
152:             .get(&name)
153:             .cloned()
154:             .expect("a version must have been previously selected");
155:         let updated_spec = if spec.version.is_none() {
156:             let mut updated_spec = spec.clone();
157:             updated_spec.version = Some(VersionSpec::Operator(
158:                 VersionOperator::StartsWith,
159:                 best_version,
160:             ));
161:             updated_spec
162:         } else {
163:             spec
164:         };
165:         let spec = MatchSpec::from_nameless(updated_spec, Some(name));
166:         match spec_type {
167:             SpecType::Host => project.add_host_dependency(&spec)?,
168:             SpecType::Build => project.add_build_dependency(&spec)?,
169:             SpecType::Run => project.add_dependency(&spec)?,
170:         }
171:         added_specs.push(spec);
172:     }
173: 
174:     // Update the lock file and write to disk
175:     let lock_file = update_lock_file(
176:         project,
177:         load_lock_file(project).await?,
178:         Some(sparse_repo_data),
179:     )
180:     .await?;
181:     project.save()?;
182: 
183:     if !no_install {
184:         let platform = Platform::current();
185:         if project.platforms().contains(&platform) {
186:             update_environment(project, &lock_file, platform).await?;
187:         } else {
188:             eprintln!("{} skipping installation of environment because your platform ({platform}) is not supported by this project.", style("!").yellow().bold())
189:         }
190:     }
191: 
192:     for spec in added_specs {
193:         eprintln!(
194:             "{}Added {}",
195:             console::style(console::Emoji("✔ ", "")).green(),
196:             spec
197:         );
198:     }
199:     Ok(())
200: }
201: 
202: async fn update_environment(
203:     project: &Project,
204:     lock_file: &CondaLock,
205:     platform: Platform,
206: ) -> miette::Result<()> {
207:     // Get the currently installed packages
208:     let prefix = Prefix::new(project.root().join(".pixi/env"))?;
209:     let installed_packages = prefix.find_installed_packages(None).await?;
210: 
211:     // Construct a transaction to bring the environment up to date with the lock-file content
212:     let transaction = Transaction::from_current_and_desired(
213:         installed_packages,
214:         get_required_packages(lock_file, platform)?,
215:         platform,
216:     )?;
217: 
218:     // Execute the transaction if there is work to do
219:     if !transaction.operations.is_empty() {
220:         // Execute the operations that are returned by the solver.
221:         await_in_progress(
222:             "updating environment",
223:             execute_transaction(
224:                 transaction,
225:                 prefix.root().to_path_buf(),
226:                 rattler::default_cache_dir()?,
227:                 AuthenticatedClient::default(),
228:             ),
229:         )
230:         .await?;
231:     }
232: 
233:     Ok(())
234: }
