236: /// Given several specs determines the highest installable version for them.
237: pub fn determine_best_version(
238:     new_specs: &HashMap<String, NamelessMatchSpec>,
239:     current_specs: &IndexMap<String, NamelessMatchSpec>,
240:     sparse_repo_data: &[SparseRepoData],
241:     platform: Platform,
242: ) -> miette::Result<HashMap<String, Version>> {
243:     let combined_specs = current_specs
244:         .iter()
245:         .chain(new_specs.iter())
246:         .map(|(name, spec)| (name.clone(), spec.clone()))
247:         .collect::<HashMap<_, _>>();
248: 
249:     // Extract the package names from all the dependencies
250:     let package_names = combined_specs.keys().cloned().collect_vec();
251: 
252:     // Get the repodata for the current platform and for NoArch
253:     let platform_sparse_repo_data = sparse_repo_data.iter().filter(|sparse| {
254:         sparse.subdir() == platform.as_str() || sparse.subdir() == Platform::NoArch.as_str()
255:     });
256: 
257:     // Load only records we need for this platform
258:     let available_packages = SparseRepoData::load_records_recursive(
259:         platform_sparse_repo_data,
260:         package_names.iter().cloned(),
261:         None,
262:     )
263:     .into_diagnostic()?;
264: 
265:     // Construct a solver task to start solving.
266:     let task = rattler_solve::SolverTask {
267:         specs: combined_specs
268:             .iter()
269:             .map(|(name, spec)| MatchSpec::from_nameless(spec.clone(), Some(name.clone())))
270:             .collect(),
271: 
272:         available_packages: &available_packages,
273: 
274:         virtual_packages: get_minimal_virtual_packages(platform)
275:             .into_iter()
276:             .map(Into::into)
277:             .collect(),
278: 
279:         // TODO: Add the information from the current lock file here.
280:         locked_packages: vec![],
281: 
282:         pinned_packages: vec![],
283:     };
284: 
285:     let records = libsolv_rs::Solver.solve(task).into_diagnostic()?;
286: 
287:     // Determine the versions of the new packages
288:     Ok(records
289:         .into_iter()
290:         .filter(|record| new_specs.contains_key(&record.package_record.name))
291:         .map(|record| {
292:             (
293:                 record.package_record.name,
294:                 record.package_record.version.into(),
295:             )
296:         })
297:         .collect())
298: }
